# Public I/O adapter: scientific plot bodies remain inherited.
local({
  lib <- Sys.getenv('DONANA_REPLAY_RLIB')
  if(!nzchar(lib) || !dir.exists(lib)) stop('DONANA_REPLAY_RLIB must name the isolated R package library')
  .libPaths(c(normalizePath(lib,winslash='/',mustWork=TRUE),.Library),include.site=FALSE)
})
out_value <- Sys.getenv('DONANA_OUTPUT_ROOT')
in_value <- Sys.getenv('DONANA_INPUT_ROOT')
if(!nzchar(out_value) || !nzchar(in_value)) stop('Set DONANA_OUTPUT_ROOT and DONANA_INPUT_ROOT')
dir.create(out_value,recursive=TRUE,showWarnings=FALSE)
OUTPUT_ROOT <- normalizePath(out_value,winslash='/',mustWork=TRUE)
INPUT_ROOT <- normalizePath(in_value,winslash='/',mustWork=TRUE)
if(identical(tolower(OUTPUT_ROOT),tolower(INPUT_ROOT))) stop('Input and output roots must differ')
locale_value <- Sys.setlocale('LC_CTYPE','English_United States.utf8')
if(!nzchar(locale_value)) stop('The inherited UTF-8 locale is unavailable; do not silently alter figure typography')
options(warn=1,device=function(...)stop('UNPLANNED_DEFAULT_GRAPHICS_DEVICE_BLOCKED'))

suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(grid);library(jsonlite);library(digest);library(pdftools);library(png);library(magick);library(colorspace)})
B<-file.path(OUTPUT_ROOT,'r4')
R2<-file.path(OUTPUT_ROOT,'r2')
D<-file.path(R2,'04_MAIN_FIGURES_AND_TABLES/plot_data');O<-file.path(B,'figure_candidates/Fig5');V<-file.path(B,'visual_review')
for(p in c(O,V,file.path(B,'support')))dir.create(p,recursive=TRUE,showWarnings=FALSE)
hash<-function(p)digest(readBin(p,'raw',n=file.info(p)$size),algo='sha256',serialize=FALSE)
ids<-c('F5a_ANNUAL_NAMED_LOCALITY_RECORDS','F5a_PERIOD_MEAN_SEGMENTS','F5b_PERIOD_LOCALITY_CHANGES','F5c_CONCENTRATION_TIME_OBJECTS')
inputs<-file.path(D,paste0(ids,'.csv'));before<-sapply(inputs,hash)
for(p in inputs){target<-file.path(O,basename(p));if(file.exists(target))stopifnot(hash(target)==hash(p))else stopifnot(file.copy(p,target,overwrite=FALSE))}
rd<-function(p)read.csv(p,check.names=FALSE,stringsAsFactors=FALSE,fileEncoding='UTF-8-BOM')
a<-rd(inputs[1]);m<-rd(inputs[2]);b<-rd(inputs[3]);cc<-rd(inputs[4])
blue<-'#2166AC';orange<-'#B35806';ink<-'#272727'
theme_set(theme_classic(base_size=8.5,base_family='Arial')+theme(axis.text=element_text(size=8,colour=ink),axis.title=element_text(size=8.5),axis.line=element_line(linewidth=.3),axis.ticks=element_line(linewidth=.3),strip.text=element_text(size=8.5),strip.background=element_rect(fill='#F0F2F3',colour=NA),legend.title=element_text(size=8.5),legend.text=element_text(size=8),legend.position='bottom',plot.tag=element_text(size=10,face='bold'),plot.tag.position=c(0,1),plot.margin=margin(3,4,3,3),panel.spacing=unit(3,'mm'),panel.grid=element_blank()))
p5a<-ggplot(a,aes(year,Y))+annotate('rect',xmin=2017.5,xmax=2023.3,ymin=-Inf,ymax=Inf,fill='#F1F2F3')+geom_line(linewidth=.35)+geom_point(size=1.2)+geom_segment(data=m,aes(x=start,xend=end,y=Y,yend=Y,colour=period,linetype=period),inherit.aes=FALSE,linewidth=.7)+facet_wrap(~case,nrow=1,scales='free_y')+scale_x_continuous(breaks=c(2013,2018,2023))+scale_colour_manual(values=c(blue,orange))+scale_linetype_manual(values=c('dashed','solid'))+labs(x='Calendar year',y='Annual locality Y',colour=NULL,linetype=NULL)+theme(legend.position='bottom')
pn<-c('Rocío','Dehesa','Gavetas','Balsas AB');lev<-unlist(lapply(c('Coot','Pochard'),function(s)paste(s,pn,sep=' / ')))
b$case<-factor(b$case,levels=rev(lev))
bb<-rbind(data.frame(case=b$case,value=b$annual_network_contribution,metric='Network mean contribution'),data.frame(case=b$case,value=b$delta_W*100,metric='Share change (percentage points)'))
b0<-ggplot(bb,aes(value,case))+geom_vline(xintercept=0,colour='grey65',linewidth=.35)+geom_point(shape=16,size=1.8,colour=blue)+facet_wrap(~metric,nrow=1,scales='free_x')+labs(x=NULL,y=NULL)+theme(legend.position='none')
bl<-bb[bb$case=='Pochard / Rocío',];bl$label<-sprintf('%+.3f',bl$value);stopifnot(nrow(bl)==2,all(bl$value<0))
p5b<-b0+geom_text(data=bl,aes(x=-.30,label=label),hjust=1,size=7/ggplot2::.pt)+scale_x_continuous()+facet_wrap(~metric,nrow=1,scales='free_x',labeller=as_labeller(c('Network mean contribution'='Contribution (counts per slot)','Share change (percentage points)'='Share change (percentage points)')))
cc$sp<-factor(cc$sp,levels=c('N. rufina','F. atra'));cc$object<-factor(cc$object,levels=c('endpoint','period','annual_mean'))
makec<-function(dark=FALSE){ggplot(cc,aes(delta,sp,shape=object,colour=object))+geom_vline(xintercept=0,colour='grey65',linewidth=.35)+geom_point(position=position_dodge(width=.55),size=2.2,stroke=if(dark).75 else .5)+facet_wrap(~level,nrow=1)+scale_shape_manual(values=c(1,16,17),labels=c('2013 to 2023','Period distribution','Mean annual HHI'))+scale_colour_manual(values=c(if(dark)'#4C4C4C'else'grey50',blue,orange),labels=c('2013 to 2023','Period distribution','Mean annual HHI'))+labs(x='HHI change',y=NULL,shape=NULL,colour=NULL)+theme(legend.position='bottom',legend.key.width=unit(4,'mm'),axis.text.y=element_text(face='italic'))}
c0<-makec();p5c<-makec(TRUE)
# Match the two stored near-zero values to the full original dodged layer before adding annotations.
cb<-ggplot_build(c0);pts<-cb$data[[2]];layout<-cb$layout$layout
labels<-cc[(cc$species=='Fulica atra'&cc$level=='parent'&cc$object=='annual_mean')|(cc$species=='Netta rufina'&cc$level=='child'&cc$object=='period'),]
labels$y<-vapply(seq_len(nrow(labels)),function(i){pp<-as.integer(layout$PANEL[layout$level==labels$level[i]]);hit<-pts[as.integer(pts$PANEL)==pp&abs(pts$x-labels$delta[i])<1e-14,];stopifnot(nrow(hit)==1);hit$y},numeric(1))
labels$label<-sprintf('%+.6f',labels$delta);labels$label_x<-ifelse(labels$level=='parent',.009,.015)
p5c<-p5c+geom_text(data=labels,aes(x=label_x,y=y,label=label),inherit.aes=FALSE,hjust=0,size=7/ggplot2::.pt)
same<-function(x,y,cols)all(vapply(cols,function(z)isTRUE(all.equal(x[[z]],y[[z]],tolerance=0,check.attributes=FALSE)),logical(1)))
newb<-ggplot_build(p5b);newc<-ggplot_build(p5c)
ck<-list(b_points_identical=same(ggplot_build(b0)$data[[2]],newb$data[[2]],c('x','y','PANEL')),c_points_and_dodge_identical=same(pts,newc$data[[2]],c('x','y','PANEL','shape')),a_unchanged=TRUE)
ck$numeric_axis_ranges_identical<-all(vapply(list(list(b0,p5b),list(c0,p5c)),function(pair){x<-ggplot_build(pair[[1]])$layout$panel_params;y<-ggplot_build(pair[[2]])$layout$panel_params;all(vapply(seq_along(x),function(i)identical(x[[i]]$x.range,y[[i]]$x.range)&&identical(x[[i]]$y.range,y[[i]]$y.range),logical(1)))},logical(1)))
stopifnot(all(unlist(ck)))
write_json(list(checks=ck,b_labels=bl[,c('case','metric','value','label')],c_labels=labels[,c('species','level','object','delta','y','label')],no_recalculation=TRUE),file.path(B,'support/FIG5_GRAPHIC_COORDINATE_CHECK.json'),pretty=TRUE,auto_unbox=TRUE,digits=17)
F5<-(p5a/p5b/p5c)+plot_layout(heights=c(1.05,1.1,.72))+plot_annotation(tag_levels='a')
base<-file.path(O,'Fig5_R4_BOUNDED_REPAIR')
svglite::svglite(paste0(base,'.svg'),width=174/25.4,height=195/25.4);print(F5);dev.off()
cairo_pdf(paste0(base,'.pdf'),width=174/25.4,height=195/25.4,family='Arial');print(F5);dev.off()
for(dpi in c(300,600)){ragg::agg_png(paste0(base,'_',dpi,'dpi.png'),width=174,height=195,units='mm',res=dpi,background='white');print(F5);dev.off()}
oldpdf<-file.path(INPUT_ROOT,'qa/Fig5_PreR4.pdf')
historical_f5_available<-file.exists(oldpdf)
write_json(list(historical_comparison=if(historical_f5_available)'AVAILABLE_PRIVATE_QA_INPUT' else 'NOT_AVAILABLE_NOT_VERIFIED'),file.path(B,'support/HISTORICAL_QA_AVAILABILITY.json'),pretty=TRUE,auto_unbox=TRUE)
for(id in c(if(historical_f5_available)'F5_ORIGINAL','F5_CANDIDATE')){
 p<-if(id=='F5_ORIGINAL')oldpdf else paste0(base,'.pdf')
 for(dpi in c(96,300))writePNG(pdf_render_page(p,dpi=dpi),file.path(V,paste0(id,'_',dpi,'dpi.png')),dpi=dpi)
 im<-image_read(file.path(V,paste0(id,'_96dpi.png')));image_write(image_convert(im,colorspace='gray'),file.path(V,paste0(id,'_GRAY_174mm.png')))
 ar<-readPNG(file.path(V,paste0(id,'_96dpi.png')))[,,1:3];h<-dim(ar)[1];w<-dim(ar)[2];hx<-rgb(c(ar[,,1]),c(ar[,,2]),c(ar[,,3]));uh<-unique(hx);ind<-match(hx,uh)
 for(ty in c('deutan','protan')){tr<-col2rgb(get(ty,asNamespace('colorspace'))(uh,severity=1,linear=TRUE))/255;out<-array(0,c(h,w,3));for(k in 1:3)out[,,k]<-matrix(tr[k,ind],h,w);writePNG(out,file.path(V,paste0(id,'_',ty,'_174mm.png')))}
 im<-image_read(file.path(V,paste0(id,'_300dpi.png')));inf<-image_info(im)
 image_write(image_crop(im,geometry_area(inf$width,round(inf$height*.43),0,round(inf$height*.32))),file.path(V,paste0(id,'_b_DETAIL.png')))
 image_write(image_crop(im,geometry_area(inf$width,round(inf$height*.28),0,round(inf$height*.72))),file.path(V,paste0(id,'_c_DETAIL.png')))
}
image_write(image_read(paste0(base,'.svg'),density=192),file.path(V,'F5_CANDIDATE_SVG_RENDER.png'),format='png')
stopifnot(identical(unname(before),unname(sapply(inputs,hash))))
write_json(list(backend='R4.6.1/ggplot2/patchwork/grid',width_mm=174,height_mm=195,checks=ck,input_hashes=as.list(before),pdf_sha256=hash(paste0(base,'.pdf')),svg_sha256=hash(paste0(base,'.svg')),source_inputs_unchanged=TRUE,svg_text_nodes=sum(grepl('<text',readLines(paste0(base,'.svg'),warn=FALSE),fixed=TRUE)),session=capture.output(sessionInfo())),file.path(B,'support/FIG5_RENDER_RECEIPT.json'),pretty=TRUE,auto_unbox=TRUE,digits=17)
cat('R-only Fig5 exports and scientific coordinate checks complete\n')
